func New() *Registry {
	return &Registry{
		registrations: make(map[string]*Registration),
	}
}

func wireMillis(meta map[string]any, key string) (time.Time, error) {
	raw, present := meta[key]
	if !present || raw == nil {
		return time.Time{}, nil
	}
	number, ok := raw.(json.Number)
	if !ok {
		return time.Time{}, errs.WrapInvalid(
			fmt.Errorf("meta.%s is a JSON %T, not integer milliseconds", key, raw),
			"BaseMessage", "UnmarshalJSON", "timestamp")
	}
	ms, err := strconv.ParseInt(number.String(), 10, 64)
	if err != nil {
		return time.Time{}, errs.WrapInvalid(
			fmt.Errorf("meta.%s %s is not integer milliseconds: %w", key, number, err),
			"BaseMessage", "UnmarshalJSON", "timestamp")
	}
	return timestamp.ToTime(ms), nil
}

func NewDecoder(reg *payloadregistry.Registry) *Decoder {
	return &Decoder{registry: reg}
}

func (pr *Registry) IndexingProfileFor(key string) (profile string, registered bool) {
	pr.mu.RLock()
	defer pr.mu.RUnlock()

	registration, exists := pr.registrations[key]
	if !exists {
		return "", false
	}
	return registration.IndexingProfile, true
}

func (g *GenericJSONPayload) RuleFields() map[string]any {
	return g.Data
}

type IndexingProfiler interface {
	// IndexingProfile returns one of "content" | "control" | "signal" | "trace".
	IndexingProfile() string
}

type Registration struct {
	Factory     Factory        `json:"-"`           // Factory function (not serializable)
	Builder     Builder        `json:"-"`           // Builder function (not serializable)
	Domain      string         `json:"domain"`      // Message domain (e.g., "robotics", "sensors")
	Category    string         `json:"category"`    // Message category (e.g., "heartbeat", "gps")
	Version     string         `json:"version"`     // Schema version (e.g., "v1", "v2")
	Description string         `json:"description"` // Human-readable description
	Example     map[string]any `json:"example"`     // Optional example payload data

	// IndexingProfile is the ADR-054 channel-(c) floor graph-ingest stamps on
	// an entity born with this type when the producer declares none. Empty
	// means the type declares no floor: ingest applies control and meters
	// the gap under indexing_profile_default_total{message_type}.
	IndexingProfile string `json:"indexing_profile,omitempty"`

	// Contracts are the projection contracts bound to this type. Each names
	// this registration's key (an empty MessageType is filled at Register);
	// a contract naming another key is a registration error.
	Contracts []contract.Contract `json:"-"`
}

func (m *BaseMessage) Hash() string {
	h := sha256.New()

	// Include message type in hash
	if _, err := h.Write([]byte(m.msgType.String())); err != nil {
		// Hash.Write() implementation in crypto/sha256 never returns an error,
		// but we handle it for interface compliance and future-proofing
		return ""
	}

	// Include payload data
	if data, err := m.payload.MarshalJSON(); err == nil {
		if _, err := h.Write(data); err != nil {
			// Hash.Write() implementation in crypto/sha256 never returns an error,
			// but we handle it for interface compliance and future-proofing
			return ""
		}
	}

	return hex.EncodeToString(h.Sum(nil))
}

type wireFormat struct {
	ID      string          `json:"id"`
	Type    Type            `json:"type"`
	Payload json.RawMessage `json:"payload"`
	Meta    map[string]any  `json:"meta"`
}

func validateSchemaConsistency(reg *Registration) error {
	testPayload := reg.Factory()
	if testPayload == nil {
		return errs.WrapInvalid(
			errs.ErrInvalidConfig,
			"PayloadRegistry",
			"Register",
			"factory returned nil payload",
		)
	}

	// Check if payload implements Schema() method
	sp, ok := testPayload.(schemaProvider)
	if !ok {
		// Payload doesn't implement Schema() - skip validation
		// This allows non-message.Payload types to be registered
		return nil
	}

	// Verify Schema() returns matching values
	schema := sp.Schema()
	if schema.Domain != reg.Domain || schema.Category != reg.Category || schema.Version != reg.Version {
		return errs.WrapInvalid(
			fmt.Errorf(
				"Schema() returns {Domain:%q Category:%q Version:%q} but registration expects {Domain:%q Category:%q Version:%q}",
				schema.Domain, schema.Category, schema.Version,
				reg.Domain, reg.Category, reg.Version,
			),
			"PayloadRegistry",
			"Register",
			"schema consistency check",
		)
	}

	return nil
}

func validString(s, at string) error {
	if !utf8.ValidString(s) {
		return fmt.Errorf("%s is not valid UTF-8", at)
	}
	return nil
}

func (pr *Registration) MessageType() string {
	return fmt.Sprintf("%s.%s.%s", pr.Domain, pr.Category, pr.Version)
}

func writeIdentityField(b *strings.Builder, field string) {
	b.WriteString(strconv.Itoa(len(field)))
	b.WriteByte(0)
	b.WriteString(field)
}

func (g *GenericJSONPayload) Validate() error {
	if g.Data == nil {
		return errs.WrapInvalid(errs.ErrInvalidData, "GenericJSONPayload", "Validate", "data cannot be nil")
	}
	return nil
}

func SameAppendTuple(left, right Triple) bool {
	return AppendIdentityKey(left) == AppendIdentityKey(right)
}

func (m *DefaultMeta) ReceivedAt() time.Time {
	return timestamp.ToTime(m.receivedAt)
}

func member(at, k string) string {
	plain := k != ""
	for _, r := range k {
		if !(r == '_' || r == '-' || '0' <= r && r <= '9' || 'a' <= r && r <= 'z' || 'A' <= r && r <= 'Z') {
			plain = false
			break
		}
	}
	if plain {
		return at + "." + k
	}
	return fmt.Sprintf("%s[%q]", at, k)
}

func (pr *Registry) Build(domain, category, version string, fields map[string]any) (any, error) {
	typeStr := fmt.Sprintf("%s.%s.%s", domain, category, version)

	pr.mu.RLock()
	registration, exists := pr.registrations[typeStr]
	pr.mu.RUnlock()

	if !exists {
		return nil, fmt.Errorf("payload type %q not registered", typeStr)
	}

	// Use custom builder if available (optimization path)
	if registration.Builder != nil {
		return registration.Builder(fields)
	}

	// Fallback: JSON round-trip using Factory
	data, err := json.Marshal(fields)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal fields for %s: %w", typeStr, err)
	}

	payload := registration.Factory()
	if err := json.Unmarshal(data, payload); err != nil {
		return nil, fmt.Errorf("failed to unmarshal into %s: %w", typeStr, err)
	}

	return payload, nil
}

func WithTime(createdAt time.Time) Option {
	return func(m *BaseMessage) {
		// Replace the default meta with one using the specified time
		if defaultMeta, ok := m.meta.(*DefaultMeta); ok {
			m.meta = NewDefaultMeta(createdAt, defaultMeta.Source())
		}
	}
}

func bindContracts(registered types.Type, floor string, contracts []contract.Contract) ([]contract.Contract, error) {
	if len(contracts) == 0 {
		return nil, nil
	}
	bound := make([]contract.Contract, 0, len(contracts))
	names := make(map[string]struct{}, len(contracts))
	for _, original := range contracts {
		c := cloneContract(original)
		if c.MessageType == (types.Type{}) {
			c.MessageType = registered
		}
		if !c.MessageType.Equal(registered) {
			return nil, errs.WrapInvalid(
				fmt.Errorf("contract %q names message type %q but is registered with %q", c.Name, c.MessageType.Key(), registered.Key()),
				"PayloadRegistry", "Register", "contract message type check")
		}
		if _, duplicate := names[c.Name]; duplicate {
			return nil, errs.WrapInvalid(
				fmt.Errorf("contract name %q repeats within registration %q", c.Name, registered.Key()),
				"PayloadRegistry", "Register", "contract name check")
		}
		names[c.Name] = struct{}{}
		if floor != "" && c.IndexingProfile != "" && c.IndexingProfile != floor {
			return nil, errs.WrapInvalid(
				fmt.Errorf("contract %q declares indexing profile %q but %q registers floor %q",
					c.Name, c.IndexingProfile, registered.Key(), floor),
				"PayloadRegistry", "Register", "contract profile agreement")
		}
		if err := c.ValidateShape(); err != nil {
			return nil, errs.WrapInvalid(
				fmt.Errorf("contract bound to %q: %w", registered.Key(), err),
				"PayloadRegistry", "Register", "contract shape validation")
		}
		bound = append(bound, c)
	}
	return bound, nil
}

func ParseEntityID(value string) (EntityID, error) {
	return types.ParseEntityID(value)
}

func NewBaseMessage(msgType Type, payload Payload, source string, opts ...Option) *BaseMessage {
	// Create message with defaults
	m := &BaseMessage{
		id:      uuid.New().String(),
		msgType: msgType,
		payload: payload,
		meta:    NewDefaultMeta(time.Now(), source),
	}

	// Apply functional options
	for _, opt := range opts {
		opt(m)
	}

	return m
}

func (m *BaseMessage) MarshalJSON() ([]byte, error) {
	// Validate before serializing - invalid messages cannot be published
	if err := m.Validate(); err != nil {
		return nil, errs.WrapInvalid(err, "BaseMessage", "MarshalJSON", "payload validation failed")
	}

	// Marshal the payload using its MarshalJSON method
	payloadData, err := m.payload.MarshalJSON()
	if err != nil {
		return nil, errs.WrapInvalid(err, "BaseMessage", "MarshalJSON", "failed to marshal payload")
	}

	// encoding/json would write each invalid byte as U+FFFD, putting a different source on the wire
	// with no error; refuse it (owner ruling 2, semengine #9). Checked here, not at construction,
	// because NewBaseMessage returns no error and WithMeta accepts any Meta.
	source := m.meta.Source()
	if !utf8.ValidString(source) {
		return nil, errs.WrapInvalid(
			fmt.Errorf("meta source %q is not valid UTF-8", source),
			"BaseMessage", "MarshalJSON", "source")
	}

	// The type is refused for the same reason (owner ruling, #9 comment 5970334875). Validate
	// above checks only that each component is non-empty.
	for _, component := range []string{m.msgType.Domain, m.msgType.Category, m.msgType.Version} {
		if !utf8.ValidString(component) {
			return nil, errs.WrapInvalid(
				fmt.Errorf("message type %q is not valid UTF-8", m.msgType.String()),
				"BaseMessage", "MarshalJSON", "type")
		}
	}

	// Create metadata map with int64 timestamps for consistency
	metaMap := map[string]interface{}{
		"created_at":  timestamp.ToUnixMs(m.meta.CreatedAt()),
		"received_at": timestamp.ToUnixMs(m.meta.ReceivedAt()),
		"source":      source,
	}

	// Create the wire format
	wire := wireFormat{
		ID:      m.id,
		Type:    m.msgType,
		Payload: json.RawMessage(payloadData),
		Meta:    metaMap,
	}

	return json.Marshal(wire)
}

func WithMeta(meta Meta) Option {
	return func(m *BaseMessage) {
		m.meta = meta
	}
}

type schemaProvider interface {
	Schema() types.Type
}

func RegisterPayloads(reg *payloadregistry.Registry) error {
	return reg.Register(&payloadregistry.Registration{
		Domain:      "core",
		Category:    "json",
		Version:     "v1",
		Description: "JSON whose shape is not known when the code is written",
		Factory: func() any {
			return &GenericJSONPayload{}
		},
		Builder: buildGenericJSONPayload,
		Example: map[string]any{
			"data": map[string]any{
				"sensor_id":   "temp-001",
				"temperature": 23.5,
				"unit":        "celsius",
			},
		},
	})
}

func buildGenericJSONPayload(fields map[string]any) (any, error) {
	msg := &GenericJSONPayload{}

	if v, ok := fields["data"].(map[string]any); ok {
		msg.Data = v
	}

	if err := msg.Validate(); err != nil {
		return nil, errs.Wrap(err, "GenericJSONPayload", "buildGenericJSONPayload", "validation failed")
	}

	return msg, nil
}

type ContentStorable interface {
	Storable // EntityID() + Triples() + StorageRef()

	// ContentFields returns semantic role → field name mapping.
	//
	// This tells consumers how to find content in the stored data without
	// hardcoding field names. Keys are semantic roles understood by consumers
	// (like embedding workers), values are field names in RawContent().
	//
	// Standard semantic roles:
	//   - "body":     Primary text content (full document text)
	//   - "abstract": Brief summary or description
	//   - "title":    Document title
	//
	// Example return value:
	//   {"body": "content", "abstract": "description", "title": "title"}
	//
	// The map should only include roles that have non-empty content.
	ContentFields() map[string]string

	// RawContent returns the content to store in ObjectStore.
	//
	// Field names in this map should match values in ContentFields().
	// This is what gets serialized and stored; consumers retrieve it
	// via StorageRef and use ContentFields to find specific content.
	//
	// Example return value:
	//   {"title": "Safety Manual", "content": "Full document text...", "description": "Brief summary"}
	RawContent() map[string]string
}

func (d *Decoder) Decode(data []byte) (*BaseMessage, error) {
	if d == nil || d.registry == nil {
		return nil, errs.WrapInvalid(
			errs.ErrInvalidConfig,
			"Decoder", "Decode", "decoder constructed with nil registry")
	}
	msg := &BaseMessage{registry: d.registry}
	if err := json.Unmarshal(data, msg); err != nil {
		return nil, err
	}
	return msg, nil
}

func (t Triple) IsRelationship() bool {
	object, ok := t.Object.(string)
	if !ok {
		return false
	}
	switch t.Datatype {
	case "", EntityReferenceDatatype:
		return IsValidEntityID(object)
	default:
		// An explicit non-reference datatype makes the object a literal even
		// when its text happens to have canonical entity-ID shape.
		return false
	}
}

func (pr *Registry) ListByDomain(domain string) []*Registration {
	pr.mu.RLock()
	defer pr.mu.RUnlock()

	var result []*Registration
	for _, registration := range pr.registrations {
		if registration.Domain == domain {
			result = append(result, registration.copyWithoutFactory())
		}
	}

	return result
}

func DedupeAppendTriples(stored, incoming []Triple) (survivors []Triple, suppressed int) {
	if len(incoming) == 0 {
		return nil, 0
	}
	seen := make(map[string]struct{}, len(stored)+len(incoming))
	for i := range stored {
		seen[AppendIdentityKey(stored[i])] = struct{}{}
	}
	survivors = make([]Triple, 0, len(incoming))
	for i := range incoming {
		key := AppendIdentityKey(incoming[i])
		if _, duplicate := seen[key]; duplicate {
			continue
		}
		seen[key] = struct{}{}
		survivors = append(survivors, incoming[i])
	}
	return survivors, len(incoming) - len(survivors)
}

func (c shapeCheck) enter(v any, n int, at string) (func(), error) {
	key := shapeKey{ptr: reflect.ValueOf(v).Pointer(), n: n}
	if c.onPath[key] {
		return nil, fmt.Errorf("%s: %T contains itself", at, v)
	}
	c.onPath[key] = true
	return func() { delete(c.onPath, key) }, nil
}

func (pr *Registry) GetRegistration(msgType string) (*Registration, bool) {
	pr.mu.RLock()
	defer pr.mu.RUnlock()

	registration, exists := pr.registrations[msgType]
	if !exists {
		return nil, false
	}

	// Return a copy to prevent external modification of the factory function
	return registration.copyWithoutFactory(), true
}

func (g *GenericJSONPayload) UnmarshalJSON(data []byte) error {
	// Use alias to avoid infinite recursion
	type Alias GenericJSONPayload
	// json.Unmarshal checks the whole input before it changes g, and refuses anything after the
	// value; a Decoder stops at the value's end, so the same check comes first here.
	if !json.Valid(data) {
		return errs.WrapInvalid(errs.ErrInvalidData, "GenericJSONPayload", "UnmarshalJSON", "not one JSON value")
	}
	d := json.NewDecoder(bytes.NewReader(data))
	d.UseNumber()
	// A well-formed value of the wrong shape (a body that is neither an object nor null, or a
	// data field that is neither an object nor null) is refused with the same invalid-data class
	// as malformed input.
	if err := d.Decode((*Alias)(g)); err != nil {
		return errs.WrapInvalid(err, "GenericJSONPayload", "UnmarshalJSON", "body or data is not a JSON object or null")
	}
	return nil
}

func (m *BaseMessage) Payload() Payload {
	return m.payload
}

type Registry struct {
	registrations map[string]*Registration // Registry by message type string
	mu            sync.RWMutex             // Protects the map
}

func (m *BaseMessage) UnmarshalJSON(data []byte) error {
	var wire wireFormat
	// UseNumber keeps each meta number's literal, so a timestamp is read as the exact integer
	// MarshalJSON wrote rather than through float64.
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	if err := decoder.Decode(&wire); err != nil {
		return errs.WrapInvalid(err, "BaseMessage", "UnmarshalJSON", "failed to unmarshal wire format")
	}

	// Set basic fields
	m.id = wire.ID
	m.msgType = wire.Type

	// Unmarshal metadata - create a DefaultMeta from the wire format.
	// Timestamps are read strictly as the integer milliseconds MarshalJSON writes (owner ruling 7,
	// semengine #9): no seconds heuristic, no other forms.
	var source string
	createdAt, err := wireMillis(wire.Meta, "created_at")
	if err != nil {
		return err
	}
	receivedAt, err := wireMillis(wire.Meta, "received_at")
	if err != nil {
		return err
	}

	if sourceStr, ok := wire.Meta["source"].(string); ok {
		source = sourceStr
	}

	m.meta = NewDefaultMetaWithReceivedAt(createdAt, receivedAt, source)

	// Fail-fast on zero-value BaseMessage — every caller, tests included,
	// must go through Decoder.
	if m.registry == nil {
		return errs.WrapInvalid(
			fmt.Errorf("no payload registry configured; use message.NewDecoder(reg).Decode(data)"),
			"BaseMessage", "UnmarshalJSON", "missing registry")
	}

	// Try to create typed payload using the registry
	payload := m.registry.Create(m.msgType.Domain, m.msgType.Category, m.msgType.Version)
	if payload == nil {
		// Unknown type - payload must be registered or use core.json.v1
		return errs.WrapInvalid(
			fmt.Errorf("unregistered payload type: %s", m.msgType.String()),
			"BaseMessage", "UnmarshalJSON", "payload type lookup")
	}

	// Unmarshal JSON into the typed payload
	if msgPayload, ok := payload.(Payload); ok {
		if err := json.Unmarshal(wire.Payload, msgPayload); err != nil {
			return errs.WrapInvalid(err, "BaseMessage", "UnmarshalJSON", "failed to unmarshal payload")
		}
		m.payload = msgPayload
	} else {
		return errs.WrapInvalid(errs.ErrInvalidData, "BaseMessage", "UnmarshalJSON", "payload does not implement message.Payload interface")
	}

	return nil
}

type DefaultMeta struct {
	createdAt  int64 // Unix milliseconds
	receivedAt int64 // Unix milliseconds
	source     string
}

type Decoder struct {
	registry *payloadregistry.Registry
}

type Triple struct {
	// Subject identifies the entity this triple describes.
	// Must use EntityID.Key() format for consistency with federated entity management.
	// Examples: "telemetry.robotics.drone.1", "gcs-alpha.robotics.drone.001"
	Subject string `json:"subject"`

	// Predicate identifies the semantic property using three-level dotted notation.
	// Format: domain.category.property (e.g., "robotics.battery.level")
	// This maintains consistency with the unified dotted notation from Alpha Week 1.
	// Predicates should be defined in the vocabulary package for consistency.
	Predicate string `json:"predicate"`

	// Object contains the property value or entity reference.
	// For literals: primitive types (float64, bool, string, int)
	// For entity references: entity ID strings using EntityID.Key() format
	// Complex objects should be flattened into multiple triples.
	Object any `json:"object"`

	// Source identifies where this assertion came from.
	// Examples: "mavlink_heartbeat", "gps_fix", "operator_input", "ai_inference"
	// Enables traceability and conflict resolution during entity merging.
	Source string `json:"source"`

	// Timestamp indicates when this assertion was made.
	// Should typically be the message timestamp or processing time.
	// Enables temporal queries and helps with entity state evolution.
	Timestamp time.Time `json:"timestamp"`

	// Confidence indicates the reliability of this assertion (0.0 to 1.0).
	// Higher values indicate greater certainty about the triple.
	//
	// Typical confidence levels:
	//   - 1.0: Direct telemetry or explicit data
	//   - 0.9: High-confidence sensor readings
	//   - 0.7: Calculated or derived values
	//   - 0.5: Inferred relationships
	//   - 0.0: Uncertain or placeholder data
	Confidence float64 `json:"confidence"`

	// Context provides correlation ID for message batches or request tracking.
	// This enables grouping related triples from the same processing batch
	// or correlating triples across distributed systems.
	// Examples: message ID, batch ID, correlation ID, request ID
	Context string `json:"context,omitempty"`

	// Datatype provides optional RDF datatype hint for the Object value.
	// This helps with type interpretation and validation in downstream systems.
	// Examples: "xsd:float", "xsd:dateTime", "xsd:boolean", "rdf:JSON"
	// If omitted, the type is inferred from the Go type of Object.
	//
	// Only the "xsd:" and "rdf:" prefixes are expanded to full IRIs on export;
	// an absolute IRI is passed through as written. Any OTHER prefix reaches
	// the output as a relative reference, which is not valid RDF — so use one
	// of those two prefixes, or write the IRI out in full. This comment used to
	// offer "geo:point" as an example and that is exactly the trap (gh#1267);
	// gh#1272 is the same mechanism one prefix over.
	Datatype string `json:"datatype,omitempty"`

	// ExpiresAt indicates when this triple should be considered expired.
	// When nil, the triple never expires and remains valid indefinitely.
	// When set, the triple is considered expired after this timestamp.
	// This enables TTL-based triple expiration for temporal data management.
	ExpiresAt *time.Time `json:"expires_at,omitempty"`
}

type BinaryContent struct {
	ContentType string // MIME type: "image/jpeg", "video/mp4", "application/pdf"
	Data        []byte // The actual binary data
}

func NewDefaultMeta(createdAt time.Time, source string) *DefaultMeta {
	return &DefaultMeta{
		createdAt:  timestamp.ToUnixMs(createdAt),
		receivedAt: timestamp.Now(),
		source:     source,
	}
}

func (c shapeCheck) list(l []any, at string) error {
	if len(l) == 0 {
		return nil
	}
	leave, err := c.enter(l, len(l), at)
	if err != nil {
		return err
	}
	defer leave()
	for i, e := range l {
		if err := c.check(e, fmt.Sprintf("%s[%d]", at, i)); err != nil {
			return err
		}
	}
	return nil
}

func (m *BaseMessage) Meta() Meta {
	return m.meta
}

type Storable interface {
	// EntityID returns deterministic 6-part ID: org.platform.system.domain.type.instance
	EntityID() string

	// Triples returns all facts about this entity
	Triples() []Triple

	// StorageRef returns reference to where full data is stored.
	// May return nil if data is not stored externally.
	StorageRef() *StorageReference
}

func (m *DefaultMeta) Source() string {
	return m.source
}

type BaseMessage struct {
	id      string
	msgType Type
	payload Payload
	meta    Meta

	// registry is the payload registry used by UnmarshalJSON to map a
	// type discriminator to an empty concrete struct. Unexported so
	// encoding/json ignores it on the wire. Set only by Decoder (same
	// package) when constructing a BaseMessage for unmarshaling. nil is
	// fail-fast: UnmarshalJSON returns a clear error pointing at
	// message.NewDecoder. There is no fallback — production code must
	// go through Decoder, and so do tests.
	registry *payloadregistry.Registry
}

type BinaryStorable interface {
	ContentStorable

	// BinaryFields returns binary content to store in ObjectStore.
	//
	// Each field is stored as a separate binary blob with its own key.
	// The returned map keys are field names that can be referenced in
	// ContentFields for semantic role mapping.
	//
	// Example return value:
	//   {"video": {ContentType: "video/mp4", Data: videoBytes},
	//    "thumbnail": {ContentType: "image/jpeg", Data: thumbBytes}}
	BinaryFields() map[string]BinaryContent
}

func NewGenericJSON(data map[string]any) *GenericJSONPayload {
	return &GenericJSONPayload{
		Data: data,
	}
}

func (m *BaseMessage) ID() string {
	return m.id
}

func (m *BaseMessage) Type() Type {
	return m.msgType
}

type GenericJSONPayload struct {
	// Data contains the JSON payload as a map of JSON-shaped values (see
	// MarshalJSON for the values it accepts).
	Data map[string]any `json:"data"`
}

func (pr *Registry) List() map[string]*Registration {
	pr.mu.RLock()
	defer pr.mu.RUnlock()

	// Return a copy to prevent external modification
	result := make(map[string]*Registration, len(pr.registrations))
	for msgType, registration := range pr.registrations {
		result[msgType] = registration.copyWithoutFactory()
	}

	return result
}

func (c shapeCheck) object(m map[string]any, at string) error {
	if len(m) == 0 {
		return nil
	}
	leave, err := c.enter(m, 0, at)
	if err != nil {
		return err
	}
	defer leave()
	// Sorted, as encoding/json writes them, so the refusal names the same key every time.
	for _, k := range slices.Sorted(maps.Keys(m)) {
		if !utf8.ValidString(k) {
			return fmt.Errorf("%s: key %q is not valid UTF-8", at, k)
		}
		if err := c.check(m[k], member(at, k)); err != nil {
			return err
		}
	}
	return nil
}

type shapeKey struct {
	ptr uintptr
	n   int
}

type Meta interface {
	// CreatedAt returns when the original event or observation occurred.
	// For sensor data, this is the measurement time.
	// For business events, this is when the event happened.
	CreatedAt() time.Time

	// ReceivedAt returns when the message entered the processing system.
	// This helps track ingestion latency and message age.
	// May be the same as CreatedAt for real-time streams.
	ReceivedAt() time.Time

	// Source returns the identifier of the message originator.
	// Examples: "gps-reader-service", "sensor-12345", "order-processor"
	// Used for debugging, tracing, and access control.
	Source() string
}

func canonicalObjectKey(object any) string {
	encoded, err := json.Marshal(object)
	if err != nil {
		return "!" + fmt.Sprintf("%#v", object)
	}
	if roundTripIsIdentity(object) {
		return string(encoded)
	}
	// Everything else keys on its PERSISTED encoding.
	var normalized any
	if err := json.Unmarshal(encoded, &normalized); err != nil {
		return string(encoded)
	}
	renormalized, err := json.Marshal(normalized)
	if err != nil {
		return string(encoded)
	}
	return string(renormalized)
}

type StorageReference struct {
	// StorageInstance identifies which storage component holds the data.
	// This enables federation across multiple storage instances.
	// Examples: "message-store", "cache-1", "objectstore-primary"
	StorageInstance string `json:"storage_instance"`

	// Key is the storage-specific key to retrieve the data.
	// Format depends on the storage backend but typically includes
	// time-based partitioning for efficient retrieval.
	// Examples: "2025/01/13/14/msg_abc123", "robotics/drone/1/latest"
	Key string `json:"key"`

	// ContentType specifies the MIME type of the stored content.
	// This helps consumers understand how to process the data.
	// Examples: "application/json", "application/protobuf", "application/avro"
	ContentType string `json:"content_type"`

	// Size is an optional hint about the stored data size in bytes.
	// This helps consumers decide whether to fetch the full data.
	// A value of 0 indicates the size is unknown.
	Size int64 `json:"size,omitempty"`
}

type RuleReadable interface {
	// RuleFields returns this payload's declared rule-readable fields.
	// A nil or empty map is a valid answer meaning "nothing to match on" —
	// distinct from not implementing the interface at all, which means the
	// payload is unreadable and the engine reports it.
	RuleFields() map[string]any
}

type Message interface {
	// ID returns a unique identifier for this message instance.
	// Typically a UUID, this ID is immutable and globally unique.
	ID() string

	// Type returns structured type information used for routing and processing.
	// The type contains domain, category, and version information.
	Type() Type

	// Payload returns the message payload that may implement behavioral interfaces.
	// Payloads expose capabilities like Storable, RuleReadable and IndexingProfiler.
	Payload() Payload

	// Meta returns metadata about the message lifecycle and origin.
	// Includes creation time, receipt time, and source service information.
	Meta() Meta

	// Hash returns a content-based hash for deduplication and storage.
	// The hash is computed from the message type and payload data.
	Hash() string

	// Validate performs comprehensive validation of the message.
	// Checks message type validity, payload presence, and payload-specific validation.
	Validate() error
}

func (pr *Registry) Create(domain, category, version string) any {
	typeStr := fmt.Sprintf("%s.%s.%s", domain, category, version)

	pr.mu.RLock()
	registration, exists := pr.registrations[typeStr]
	pr.mu.RUnlock()

	if !exists {
		return nil
	}

	return registration.Factory()
}

func AppendIdentityKey(t Triple) string {
	var b strings.Builder
	// Rough preallocation; the object encoding dominates and is unknown here.
	b.Grow(len(t.Subject) + len(t.Predicate) + len(t.Datatype) + len(t.Source) + len(t.Context) + 48)
	writeIdentityField(&b, t.Subject)
	writeIdentityField(&b, t.Predicate)
	writeIdentityField(&b, t.Datatype)
	writeIdentityField(&b, t.Source)
	writeIdentityField(&b, t.Context)
	writeIdentityField(&b, canonicalObjectKey(t.Object))
	return b.String()
}

