func cloneContracts(contracts []contract.Contract) []contract.Contract {
	if len(contracts) == 0 {
		return nil
	}
	cloned := make([]contract.Contract, len(contracts))
	for index, c := range contracts {
		cloned[index] = cloneContract(c)
	}
	return cloned
}

func (c shapeCheck) check(v any, at string) error {
	switch v := v.(type) {
	case nil, bool,
		int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64, uintptr,
		float32, float64:
		return nil
	case string:
		return validString(v, at)
	case json.Number:
		return validString(string(v), at)
	case map[string]any:
		return c.object(v, at)
	case []any:
		return c.list(v, at)
	default:
		return fmt.Errorf("%s: %T is not JSON-shaped (want map[string]any, []any, string, a Go number, "+
			"json.Number, bool or nil)", at, v)
	}
}

func (pr *Registry) Contracts() []contract.Contract {
	pr.mu.RLock()
	defer pr.mu.RUnlock()

	keys := make([]string, 0, len(pr.registrations))
	for key, registration := range pr.registrations {
		if len(registration.Contracts) != 0 {
			keys = append(keys, key)
		}
	}
	sort.Strings(keys)

	var result []contract.Contract
	for _, key := range keys {
		contracts := cloneContracts(pr.registrations[key].Contracts)
		sort.Slice(contracts, func(i, j int) bool { return contracts[i].Name < contracts[j].Name })
		result = append(result, contracts...)
	}
	return result
}

func (g *GenericJSONPayload) Schema() Type {
	return Type{
		Domain:   "core",
		Category: "json",
		Version:  "v1",
	}
}

func roundTripIsIdentity(object any) bool {
	switch object.(type) {
	case nil, bool, string:
		return true
	default:
		return false
	}
}

func cloneContract(c contract.Contract) contract.Contract {
	clone := c
	clone.BirthPredicates = append([]string(nil), c.BirthPredicates...)
	clone.Groups = make([]contract.PredicateGroup, len(c.Groups))
	for index, group := range c.Groups {
		clone.Groups[index] = group
		clone.Groups[index].Predicates = append([]string(nil), group.Predicates...)
	}
	return clone
}

func (g *GenericJSONPayload) MarshalJSON() ([]byte, error) {
	// Only the ruled kinds are accepted (#9 comments 5972117486 and 5972208367), so encoding/json
	// runs no custom method and writes every string as it is; invalid UTF-8 is refused rather than
	// written as U+FFFD (#9 comment 5970334875).
	if err := (shapeCheck{onPath: map[shapeKey]bool{}}).check(g.Data, "data"); err != nil {
		return nil, errs.WrapInvalid(err, "GenericJSONPayload", "MarshalJSON", "data")
	}
	// Use alias to avoid infinite recursion
	type Alias GenericJSONPayload
	return json.Marshal((*Alias)(g))
}

